package com.bankstackvalues;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup(BankStackValuesConfig.GROUP)
public interface BankStackValuesConfig extends Config
{
    String GROUP = "bankstackvalues";

    @ConfigItem(keyName = "overlayEnabled", name = "Show stack values",
        description = "Also controlled by the in-bank button", position = 0)
    default boolean overlayEnabled() { return true; }

    @ConfigItem(keyName = "valueType", name = "Value type",
        description = "Show GE or High Alch value for each stack", position = 1)
    default ValueType valueType() { return ValueType.GE; }

    @ConfigItem(keyName = "hideUntradableValues", name = "Hide untradable values",
        description = "Hide values for items marked as untradable, even when they have a mapped price", position = 2)
    default boolean hideUntradableValues() { return false; }

    @ConfigItem(keyName = "useDefaultColorForAllStacks", name = "Use default colour for all stacks",
        description = "Use the default colour regardless of total stack value", position = 3)
    default boolean useDefaultColorForAllStacks() { return false; }

    @ConfigItem(keyName = "textColor", name = "Default colour",
        description = "Colour for stacks worth at most 10k, or all stacks when enabled above", position = 4)
    default Color textColor() { return Color.WHITE; }

    @ConfigItem(keyName = "over10kColor", name = ">10k colour",
        description = "Colour for total stack values between 10,000 gp and 100,000 gp", position = 5)
    default Color over10kColor() { return new Color(0x66B2FF); }

    @ConfigItem(keyName = "over100kColor", name = ">100k colour",
        description = "Colour for total stack values between 100,000 gp and 1,000,000 gp", position = 6)
    default Color over100kColor() { return new Color(0x99FF99); }

    @ConfigItem(keyName = "over1mColor", name = ">1m colour",
        description = "Colour for total stack values between 1,000,000 gp and 10,000,000 gp", position = 7)
    default Color over1mColor() { return new Color(0xFF9600); }

    @ConfigItem(keyName = "over10mColor", name = ">10m colour",
        description = "Colour for total stack values greater than 10,000,000 gp", position = 8)
    default Color over10mColor() { return new Color(0xFF66B2); }

    @ConfigItem(keyName = "buttonRightOffset", name = "Button right offset",
        description = "Pixels from the right edge of the bank; adjust if another plugin overlaps", position = 9)
    @Range(min = 25, max = 350)
    default int buttonRightOffset() { return 35; }

    @ConfigItem(keyName = "buttonTopOffset", name = "Button top offset",
        description = "Pixels from the top of the bank", position = 10)
    @Range(min = 0, max = 40)
    default int buttonTopOffset() { return 6; }
}

package com.bankstackvalues;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

class BankStackValuesOverlay extends WidgetItemOverlay
{
    private final BankStackValuesConfig config;
    private final StackValue values;

    @Inject
    BankStackValuesOverlay(BankStackValuesConfig config, StackValue values)
    {
        this.config = config;
        this.values = values;
        drawAfterLayer(InterfaceID.Bankmain.ITEMS);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item)
    {
        // Excludes tab icons, inventory, potion storage and other bank controls.
        if (!config.overlayEnabled() || item.getWidget().getId() != InterfaceID.Bankmain.ITEMS)
        {
            return;
        }
        // Bank Tags layouts use a real item ID with this dummy quantity for missing items.
        // Check the quantity mode too so genuine maximum-size stacks still get a value.
        if (item.getQuantity() == Integer.MAX_VALUE
            && item.getWidget().getItemQuantityMode() == ItemQuantityMode.NEVER)
        {
            return;
        }
        long total = values.total(itemId, item.getQuantity(), config.hideUntradableValues(), config.valueType());
        if (total <= 0) { return; }
        String text = StackValue.format(total);
        Rectangle bounds = item.getCanvasBounds();
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setFont(FontManager.getRunescapeSmallFont());
            int width = g.getFontMetrics().stringWidth(text);
            // Keep even unusually large values within their own item slot.
            if (width > bounds.width && bounds.width > 0)
            {
                g.setFont(g.getFont().deriveFont(g.getFont().getSize2D() * bounds.width / width));
                width = g.getFontMetrics().stringWidth(text);
            }
            int x = bounds.x + (bounds.width - width) / 2;
            int y = bounds.y + bounds.height - 1;
            g.setColor(Color.BLACK);
            g.drawString(text, x + 1, y + 1);
            g.setColor(colorForValue(total));
            g.drawString(text, x, y);
        }
        finally { g.dispose(); }
    }

    private Color colorForValue(long total)
    {
        if (config.useDefaultColorForAllStacks()) { return config.textColor(); }
        if (total > 10_000_000) { return config.over10mColor(); }
        if (total > 1_000_000) { return config.over1mColor(); }
        if (total > 100_000) { return config.over100kColor(); }
        if (total > 10_000) { return config.over10kColor(); }
        return config.textColor();
    }
}

package com.bankstackvalues;

import com.google.inject.Provides;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Bank Stack Values",
    description = "Shows each bank stack's GE or High Alch value with an in-bank toggle",
    tags = {"bank", "ge", "alch", "price", "stack", "value"})
public class BankStackValuesPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private BankStackValuesConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private BankStackValuesOverlay overlay;

    private Widget parent;
    private Widget background;
    private Widget button;
    private volatile boolean running;

    @Provides
    BankStackValuesConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(BankStackValuesConfig.class);
    }

    @Override
    protected void startUp()
    {
        running = true;
        overlayManager.add(overlay);
        clientThread.invokeLater(() -> { if (running) { updateButton(); } });
    }

    @Override
    protected void shutDown()
    {
        running = false;
        overlayManager.remove(overlay);
        clientThread.invokeLater(() -> { if (!running) { removeButton(); } });
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (running) { updateButton(); }
    }

    private void updateButton()
    {
        Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (bank == null || bank.isHidden() || items == null || items.isHidden())
        {
            removeButton();
            return;
        }
        // Bank scripts can rebuild the children without replacing the parent.
        if (parent != bank || !attached(button) || !attached(background))
        {
            removeButton();
            parent = bank;
            background = bank.createChild(-1, WidgetType.RECTANGLE);
            background.setFilled(true);
            button = bank.createChild(-1, WidgetType.TEXT);
            button.setFontId(494); // RuneScape's small bitmap font
            button.setTextShadowed(true);
            button.setXTextAlignment(1);
            button.setYTextAlignment(1);
            button.setHasListener(true);
            button.setOnOpListener((JavaScriptCallback) event ->
            {
                if (running)
                {
                    configManager.setConfiguration(BankStackValuesConfig.GROUP,
                        "overlayEnabled", !config.overlayEnabled());
                    updateButton();
                }
            });
        }
        boolean enabled = config.overlayEnabled();
        String valueLabel = config.valueType().toString();
        String buttonLabel = config.valueType() == ValueType.HIGH_ALCH ? "HA" : "GE";
        button.setName("Bank stack " + valueLabel + " values");
        background.setTextColor(enabled ? 0x425134 : 0x423b32);
        button.setText(buttonLabel + (enabled ? ": ON" : ": OFF"));
        button.setTextColor(enabled ? 0xffdc64 : 0xc8c0b0);
        button.setAction(0, enabled ? "Hide" : "Show");
        for (Widget widget : new Widget[]{background, button})
        {
            widget.setOriginalWidth(64);
            widget.setOriginalHeight(18);
            widget.setXPositionMode(2); // Anchor to the right on resize.
            widget.setOriginalX(config.buttonRightOffset());
            widget.setOriginalY(config.buttonTopOffset());
            widget.revalidate();
        }
    }

    private boolean attached(Widget widget)
    {
        return parent != null && widget != null && parent.getChild(widget.getIndex()) == widget;
    }

    private void removeButton()
    {
        if (parent != null)
        {
            Widget[] children = parent.getChildren();
            if (children != null)
            {
                children = children.clone();
                for (int i = 0; i < children.length; i++)
                {
                    if (children[i] == button || children[i] == background) { children[i] = null; }
                }
                int length = children.length;
                while (length > 0 && children[length - 1] == null) { length--; }
                // Preserve other plugins' widgets and their indices.
                parent.setChildren(Arrays.copyOf(children, length));
            }
        }
        parent = null;
        background = null;
        button = null;
    }
}

package com.bankstackvalues;

import java.math.BigDecimal;
import java.math.RoundingMode;
import javax.inject.Inject;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

final class StackValue
{
    private final ItemManager itemManager;

    @Inject
    StackValue(ItemManager itemManager) { this.itemManager = itemManager; }

    long total(int itemId, int quantity, boolean hideUntradableValues, ValueType valueType)
    {
        if (itemId <= 0 || quantity <= 0) { return 0; }
        ItemComposition item = itemManager.getItemComposition(itemId);
        if (item.getPlaceholderTemplateId() != -1) { return 0; }
        if (hideUntradableValues && !item.isTradeable()) { return 0; }
        // Match RuneLite's Bank plugin, including currency face values in HA mode.
        long price;
        if (valueType == ValueType.HIGH_ALCH)
        {
            price = itemId == ItemID.COINS ? 1
                : itemId == ItemID.PLATINUM ? 1000 : item.getHaPrice();
        }
        else
        {
            price = itemManager.getItemPrice(itemId);
        }
        if (price <= 0) { return 0; }
        // Mapped GE prices can exceed int range. Keep extreme stack totals positive.
        return price > Long.MAX_VALUE / quantity ? Long.MAX_VALUE : price * quantity;
    }

    static String format(long value)
    {
        if (value < 1_000) { return Long.toString(value); }
        long divisor;
        String suffix;
        if (value >= 1_000_000_000_000L) { divisor = 1_000_000_000_000L; suffix = "T"; }
        else if (value >= 1_000_000_000) { divisor = 1_000_000_000; suffix = "B"; }
        else if (value >= 1_000_000) { divisor = 1_000_000; suffix = "M"; }
        else { divisor = 1_000; suffix = "K"; }
        return BigDecimal.valueOf(value).divide(BigDecimal.valueOf(divisor),
            value / divisor < 100 ? 1 : 0, RoundingMode.DOWN)
            .stripTrailingZeros().toPlainString() + suffix;
    }
}

package com.bankstackvalues;

public enum ValueType
{
    GE("GE"),
    HIGH_ALCH("High Alch");

    private final String label;

    ValueType(String label) { this.label = label; }

    @Override
    public String toString() { return label; }
}

