package com.bankstackvalues;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BankStackValuesOverlayTest
{
    private ItemManager manager;
    private Widget widget;
    private WidgetItem item;
    private BankStackValuesOverlay overlay;
    private boolean hideUntradableValues;
    private BankStackValuesConfig config;

    @Before public void setUp()
    {
        manager = mock(ItemManager.class);
        ItemComposition definition = mock(ItemComposition.class);
        when(definition.getPlaceholderTemplateId()).thenReturn(-1);
        when(manager.getItemComposition(100)).thenReturn(definition);
        when(manager.getItemPrice(100)).thenReturn(250L);
        widget = mock(Widget.class);
        when(widget.getId()).thenReturn(InterfaceID.Bankmain.ITEMS);
        item = mock(WidgetItem.class);
        when(item.getWidget()).thenReturn(widget);
        when(item.getCanvasBounds()).thenReturn(new Rectangle(0, 0, 36, 32));
        config = spy(new BankStackValuesConfig()
        {
            @Override public boolean hideUntradableValues() { return hideUntradableValues; }
        });
        overlay = new BankStackValuesOverlay(config, new StackValue(manager));
    }

    private BufferedImage render()
    {
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try { overlay.renderItemOverlay(graphics, 100, item); }
        finally { graphics.dispose(); }
        return image;
    }

    private void assertLabelColor(Color expected)
    {
        BufferedImage image = render();
        boolean found = false;
        for (int y = 0; y < image.getHeight(); y++)
        {
            for (int x = 0; x < image.getWidth(); x++)
            {
                int pixel = image.getRGB(x, y);
                if (pixel == 0 || pixel == Color.BLACK.getRGB()) { continue; }
                assertEquals(expected.getRGB(), pixel);
                found = true;
            }
        }
        assertTrue("Expected a visible value label", found);
    }

    @Test public void usesDefaultTierColorsWithStrictThresholds()
    {
        int[] prices = {1, 10_000, 10_001, 100_000, 100_001,
            1_000_000, 1_000_001, 10_000_000, 10_000_001};
        int[] colors = {0xFFFFFF, 0xFFFFFF, 0x66B2FF, 0x66B2FF, 0x99FF99,
            0x99FF99, 0xFF9600, 0xFF9600, 0xFF66B2};
        when(item.getQuantity()).thenReturn(1);
        for (int i = 0; i < prices.length; i++)
        {
            when(manager.getItemPrice(100)).thenReturn((long) prices[i]);
            assertLabelColor(new Color(colors[i]));
        }
    }

    @Test public void usesTotalStackValueAndAppliesColorSettingsImmediately()
    {
        when(item.getQuantity()).thenReturn(500); // 250 gp each, 125k total.
        assertLabelColor(new Color(0x99FF99));
        when(config.over100kColor()).thenReturn(Color.RED);
        assertLabelColor(Color.RED);
        when(config.textColor()).thenReturn(Color.CYAN);
        when(config.useDefaultColorForAllStacks()).thenReturn(true);
        assertLabelColor(Color.CYAN);
        when(config.useDefaultColorForAllStacks()).thenReturn(false);
        assertLabelColor(Color.RED);
    }

    @Test public void usesCustomColorsForEveryTier()
    {
        when(config.textColor()).thenReturn(Color.RED);
        when(config.over10kColor()).thenReturn(Color.BLUE);
        when(config.over100kColor()).thenReturn(Color.GREEN);
        when(config.over1mColor()).thenReturn(Color.YELLOW);
        when(config.over10mColor()).thenReturn(Color.MAGENTA);
        int[] prices = {1, 10_001, 100_001, 1_000_001, 10_000_001};
        Color[] colors = {Color.RED, Color.BLUE, Color.GREEN, Color.YELLOW, Color.MAGENTA};
        when(item.getQuantity()).thenReturn(1);
        for (int i = 0; i < prices.length; i++)
        {
            when(manager.getItemPrice(100)).thenReturn((long) prices[i]);
            assertLabelColor(colors[i]);
        }
    }

    @Test public void switchingValueTypeImmediatelyChangesValueAndColorTier()
    {
        when(item.getQuantity()).thenReturn(500);
        when(manager.getItemComposition(100).getHaPrice()).thenReturn(30);
        assertLabelColor(config.over100kColor()); // GE: 125k.
        when(config.valueType()).thenReturn(ValueType.HIGH_ALCH);
        assertLabelColor(config.over10kColor()); // HA: 15k.
        when(config.valueType()).thenReturn(ValueType.GE);
        assertLabelColor(config.over100kColor());
    }

    @Test public void appliesUntradableSettingChanges()
    {
        when(item.getQuantity()).thenReturn(500);
        hideUntradableValues = true;
        render();
        verify(manager, never()).getItemPrice(anyInt());
        hideUntradableValues = false;
        render();
        verify(manager).getItemPrice(100);
    }

    @Test public void skipsBankTagLayoutPlaceholdersWithRealItemIds()
    {
        when(item.getQuantity()).thenReturn(Integer.MAX_VALUE);
        when(widget.getItemQuantityMode()).thenReturn(ItemQuantityMode.NEVER);
        render();
        verifyNoInteractions(manager);
    }

    @Test public void valuesRealMaximumSizeStacks()
    {
        when(item.getQuantity()).thenReturn(Integer.MAX_VALUE);
        when(widget.getItemQuantityMode()).thenReturn(ItemQuantityMode.STACKABLE);
        render();
        verify(manager).getItemPrice(100);
    }

    @Test public void valuesOrdinaryStacksWithHiddenQuantityText()
    {
        when(item.getQuantity()).thenReturn(500);
        when(widget.getItemQuantityMode()).thenReturn(ItemQuantityMode.NEVER);
        render();
        verify(manager).getItemPrice(100);
    }
}

package com.bankstackvalues;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BankStackValuesPluginTest
{
    private BankStackValuesPlugin plugin;
    private Client client;
    private Widget bank;
    private Widget other;
    private List<Widget> children;
    private ConfigManager manager;
    private AtomicBoolean enabled;
    private ClientThread thread;
    private ValueType valueType = ValueType.GE;

    private void inject(String name, Object value) throws Exception
    {
        Field field = BankStackValuesPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }

    @Before public void setUp() throws Exception
    {
        plugin = new BankStackValuesPlugin();
        client = mock(Client.class);
        bank = mock(Widget.class);
        other = mock(Widget.class);
        children = new ArrayList<>();
        children.add(other);
        when(client.getWidget(InterfaceID.Bankmain.UNIVERSE)).thenReturn(bank);
        when(client.getWidget(InterfaceID.Bankmain.ITEMS)).thenReturn(mock(Widget.class));
        when(bank.getChildren()).thenAnswer(i -> children.toArray(new Widget[0]));
        when(bank.getChild(anyInt())).thenAnswer(i ->
        {
            int index = i.getArgument(0);
            return index < children.size() ? children.get(index) : null;
        });
        doAnswer(i ->
        {
            children = new ArrayList<>(Arrays.asList((Widget[]) i.getArgument(0)));
            return null;
        }).when(bank).setChildren(any(Widget[].class));
        when(bank.createChild(eq(-1), anyInt())).thenAnswer(i ->
        {
            Widget widget = mock(Widget.class);
            when(widget.getIndex()).thenReturn(children.size());
            children.add(widget);
            return widget;
        });
        enabled = new AtomicBoolean(true);
        BankStackValuesConfig config = new BankStackValuesConfig()
        {
            @Override public boolean overlayEnabled() { return enabled.get(); }
            @Override public ValueType valueType() { return valueType; }
        };
        manager = mock(ConfigManager.class);
        thread = mock(ClientThread.class);
        inject("client", client);
        inject("clientThread", thread);
        inject("configManager", manager);
        inject("config", config);
        inject("overlayManager", mock(OverlayManager.class));
        inject("overlay", mock(BankStackValuesOverlay.class));
        plugin.startUp();
        plugin.onClientTick(new ClientTick());
    }

    @Test public void buttonIsCreatedOnceAndReflectsSetting()
    {
        assertEquals(3, children.size());
        Widget button = children.get(2);
        verify(button).setText("GE: ON");
        enabled.set(false);
        plugin.onClientTick(new ClientTick());
        assertEquals(3, children.size());
        verify(button).setText("GE: OFF");
    }

    @Test public void buttonReflectsValueTypeChangesWithoutRecreation()
    {
        Widget button = children.get(2);
        valueType = ValueType.HIGH_ALCH;
        plugin.onClientTick(new ClientTick());
        verify(button).setText("HA: ON");
        verify(button).setName("Bank stack High Alch values");
        verify(button, times(2)).setAction(0, "Hide");
        enabled.set(false);
        plugin.onClientTick(new ClientTick());
        verify(button).setText("HA: OFF");
        verify(button).setAction(0, "Show");
        valueType = ValueType.GE;
        plugin.onClientTick(new ClientTick());
        verify(button).setText("GE: OFF");
        assertEquals(3, children.size());
    }

    @Test public void clickPersistsBothToggleDirections()
    {
        ArgumentCaptor<JavaScriptCallback> callback = ArgumentCaptor.forClass(JavaScriptCallback.class);
        verify(children.get(2)).setOnOpListener(callback.capture());
        callback.getValue().run(null);
        verify(manager).setConfiguration(BankStackValuesConfig.GROUP, "overlayEnabled", false);
        enabled.set(false);
        callback.getValue().run(null);
        verify(manager).setConfiguration(BankStackValuesConfig.GROUP, "overlayEnabled", true);
    }

    @Test public void closeAndReopenPreserveOtherWidgets()
    {
        when(bank.isHidden()).thenReturn(true);
        plugin.onClientTick(new ClientTick());
        assertEquals(1, children.size());
        assertSame(other, children.get(0));
        when(bank.isHidden()).thenReturn(false);
        plugin.onClientTick(new ClientTick());
        assertEquals(3, children.size());
    }

    @Test public void rebuildRestoresButton()
    {
        children = new ArrayList<>(Arrays.asList(other));
        plugin.onClientTick(new ClientTick());
        assertEquals(3, children.size());
        verify(children.get(2)).setText("GE: ON");
    }

    @Test public void shutdownRemovesOnlyOurWidgets()
    {
        Widget laterPluginWidget = mock(Widget.class);
        children.add(laterPluginWidget);
        // Execute queued client-thread cleanup synchronously in this test.
        doAnswer(i -> { ((Runnable) i.getArgument(0)).run(); return null; })
            .when(thread).invokeLater(any(Runnable.class));
        plugin.shutDown();
        assertSame(other, children.get(0));
        assertNull(children.get(1));
        assertNull(children.get(2));
        assertSame(laterPluginWidget, children.get(3));
    }
}

package com.bankstackvalues;

import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StackValueTest
{
    private ItemManager manager;
    private ItemComposition item;
    private StackValue values;

    @Before public void setUp()
    {
        manager = mock(ItemManager.class);
        item = mock(ItemComposition.class);
        when(item.getPlaceholderTemplateId()).thenReturn(-1);
        when(manager.getItemComposition(100)).thenReturn(item);
        values = new StackValue(manager);
    }

    @Test public void multipliesUnitPriceByStackQuantity()
    {
        when(manager.getItemPrice(100)).thenReturn(250L);
        assertEquals(125_000L, values.total(100, 500, false, ValueType.GE));
    }

    @Test public void hidesUntradableItemsWithMappedPrices()
    {
        when(manager.getItemPrice(100)).thenReturn(250L);
        assertEquals(0, values.total(100, 500, true, ValueType.GE));
        verify(manager, never()).getItemPrice(anyInt());
    }

    @Test public void keepsTradableValuesWhenHidingUntradables()
    {
        when(item.isTradeable()).thenReturn(true);
